def combinations(n, k):
    out = []
    def go(start, cur):
        if len(cur) == k:
            out.append(cur[:])
            return
        for x in range(start, n + 1):
            cur.append(x)
            go(x + 1, cur)
            cur.pop()
    go(1, [])
    return out
